/// File extension/name mappings
pub syntax_mapping: SyntaxMapping<'a>,

/// Filename suffixes that should be ignored during syntax detection
pub ignored_suffixes: Vec<String>,

/// Detect the syntax based on, in order:
///  1. Syntax mappings with [MappingTarget::MapTo] and [MappingTarget::MapToUnknown]
///     (e.g. `/etc/profile` -> `Bourne Again Shell (bash)`)
///  2. The file name (e.g. `Dockerfile`)
///  3. Syntax mappings with [MappingTarget::MapExtensionToUnknown]
///     (e.g. `*.conf`)
///  4. The file name extension (e.g. `.rs`)
///
/// When detecting syntax based on syntax mappings, the full path is taken
/// into account. When detecting syntax based on file name, no regard is
/// taken to the path of the file. Only the file name itself matters. When
/// detecting syntax based on file name extension, only the file name
/// extension itself matters.
///
/// Filename suffixes in `ignored_suffixes` (custom suffixes provided by
/// the user, e.g. via `--ignored-suffix`) are stripped from the file name
/// (in addition to the built-in ignored suffixes) before syntax detection
/// is retried on the stripped file name.
///
/// Returns [Error::UndetectedSyntax] if it was not possible detect syntax
/// based on path/file name/extension (or if the path was mapped to
/// [MappingTarget::MapToUnknown] or [MappingTarget::MapExtensionToUnknown]).
/// In this case it is appropriate to fall back to other methods to detect
/// syntax. Such as using the contents of the first line of the file.
///
/// Returns [Error::UnknownSyntax] if a syntax mapping exist, but the mapped
/// syntax does not exist.
pub fn get_syntax_for_path(
    &self,
    path: impl AsRef<Path>,
    mapping: &SyntaxMapping,
    ignored_suffixes: &[String],
) -> Result<SyntaxReferenceInSet> {
    let path = path.as_ref();
    let ignored_suffixes = get_ignored_suffixes(ignored_suffixes);

    let candidate = Candidate::new(path);
    let candidate_filename = path.file_name().map(Candidate::new);
    let mut syntax_match = None;
    for (glob, target) in mapping.mappings().iter().rev() {
        if glob.is_match_candidate(&candidate)
            || candidate_filename
                .as_ref()
                .map_or(false, |filename| glob.is_match_candidate(filename))
        {
            syntax_match = Some(*target);
            break;
        }
    }

    if let Some(MappingTarget::MapToUnknown) = syntax_match {
        return Err(Error::UndetectedSyntax(path.to_string_lossy().into()));
    }

    let syntax_set = self.syntax_set_cell.try_borrow_with(|| {
        match &self.serialized_syntax_set {
            SerializedSyntaxSet::FromBinary(data) => {
                Ok(from_binary(data, COMPRESS_SYNTAXES))
            }
            SerializedSyntaxSet::FromFile(cache_path) => {
                asset_from_cache(cache_path, "syntax set", COMPRESS_SYNTAXES)
            }
        }
    })?;

    if let Some(MappingTarget::MapTo(syntax_name)) = syntax_match {
        return syntax_set
            .find_syntax_by_name(syntax_name)
            .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set })
            .ok_or_else(|| Error::UnknownSyntax(syntax_name.to_owned()));
    }

    let file_name = path.file_name().unwrap_or_default();

    let mut current_file_name = file_name.to_os_string();
    let mut syntax_from_file_name = None;
    loop {
        // Check if the (possibly stripped) file name is mapped to a syntax
        // by a user provided syntax mapping, e.g. via `--map-syntax`.
        let candidate = Candidate::new(Path::new(&current_file_name));
        for (glob, target) in mapping.mappings().iter().rev() {
            if glob.is_match_candidate(&candidate) {
                if let MappingTarget::MapTo(syntax_name) = target {
                    return syntax_set
                        .find_syntax_by_name(syntax_name)
                        .map(|syntax| SyntaxReferenceInSet { syntax, syntax_set })
                        .ok_or_else(|| Error::UnknownSyntax(syntax_name.to_owned()));
                }
                break;
            }
        }

        let file_name_token = current_file_name.to_str().unwrap_or_default();
        if let Some(syntax) = syntax_set.find_syntax_by_extension(file_name_token) {
            syntax_from_file_name = Some(SyntaxReferenceInSet { syntax, syntax_set });
            break;
        }

        let stripped = try_with_stripped_suffix(
            &current_file_name,
            &ignored_suffixes,
            |stripped_file_name| Ok(Some(OsString::from(stripped_file_name))),
        )?;
        if let Some(stripped_file_name) = stripped {
            current_file_name = stripped_file_name;
        } else {
            break;
        }
    }

