fn get_syntax_for_file_name(
    &self,
    file_name: &OsStr,
    ignored_suffixes: &[String],
) -> Result<Option<SyntaxReferenceInSet>> {
    let mut syntax = self.find_syntax_by_extension(Some(file_name))?;
    if syntax.is_none() {
        syntax = try_with_stripped_suffix(file_name, ignored_suffixes, |stripped_file_name| {
            self.get_syntax_for_file_name(stripped_file_name, ignored_suffixes) // Note: recursion
        })?;
    }
    Ok(syntax)
}

